echo '...' >#{lotl_gtfobins_local_path}
nmap --script=#{lotl_gtfobins_local_path}
lua -e 'local f=io.open("#{lotl_gtfobins_output_file}", "wb"); f:write("#{lotl_gtfobins_data}"); io.close(f);'

echo '...' >#{lotl_gtfobins_local_path}
pandoc -L #{lotl_gtfobins_local_path} /dev/null
